// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.vision.barcodeimport timber.log.Timberimport android.content.Contextimport android.content.Intentimport android.net.Uri/** * NOUS — UPI QR Handler (Module 6 v4 — Step 6.4, India-First). * * Handles UPI QR code scanning → payment intent launch, per strategy v3 * §"India-First Design" + v4 §"Regional Vision Packs". * * ## What it does * *  1. **Receives a parsed [QrPayload.UpiPayload]** from [BarcodeScannerEngine]. *  2. **Validates the UPI ID** — checks format (name@bank, length 5-100). *  3. **Builds a payment intent** — `Intent.ACTION_VIEW` with `upi://pay?...` URI. *  4. **Launches the intent** — opens the user's default UPI app (GPay/PhonePe/Paytm/BHIM). *  5. **Supports regional QR formats** — Pix (Brazil), PromptPay (Thailand), DuitNow (Malaysia). * * ## India-First (per strategy v4 §"India-First Design") * * UPI (Unified Payments Interface) is the dominant payment system in India — * 9 billion transactions/month (2024). Every merchant has a UPI QR code. * * NOUS's UPI QR handler lets users scan any merchant QR and pay with their * preferred UPI app — **no need to open the app manually + navigate to "Scan"**. * * Just say: *"NOUS, scan this UPI QR"* → camera opens → scan → payment intent → done. * * ## Regional QR Support (per strategy v4 §"Regional Vision Packs") * * | Region | Payment System | QR Format | * |--------|---------------|-----------| * | India | UPI | `upi://pay?pa=...` | * | Brazil | Pix | EMV QR (tag 26) | * | Thailand | PromptPay | EMV QR (tag 29) | * | Malaysia | DuitNow | EMV QR (tag 26) | * * ## Privacy * *  - UPI IDs are NOT logged or persisted — only used to build the payment intent. *  - The payment intent launches the user's UPI app — NOUS does NOT process the *    payment itself. *  - No transaction data is sent to NOUS servers. * * @see <a href="docs/strategy/module-6-vision-strategy-v4.md">§Step 6.4: UpiQrHandler</a> */class UpiQrHandler(    private val context: Context,    private val region: RegionalQrFormat = RegionalQrFormat.INDIA,) {    /**     * Handle a scanned UPI QR code — build + launch the payment intent.     *     * @param payload the parsed UPI payload.     * @return the [PaymentIntentResult] — SUCCESS, INVALID_PAYLOAD, NO_UPI_APP, or FAILED.     */    suspend fun handleUpiQr(payload: QrPayload.UpiPayload): PaymentIntentResult {        Timber.tag(TAG).i("Handling UPI QR: upiId=${payload.upiId}, amount=${payload.amount}, region=$region")        // 1. Validate region supports UPI.        if (!region.supports(QrPayloadType.UPI)) {            Timber.tag(TAG).w("UPI not supported in region $region.")            return PaymentIntentResult.REGION_NOT_SUPPORTED(region)        }        // 2. Validate UPI ID format.        if (!payload.isValidUpiId) {            Timber.tag(TAG).w("Invalid UPI ID: ${payload.upiId}")            return PaymentIntentResult.INVALID_PAYLOAD("Invalid UPI ID: ${payload.upiId}")        }        // 3. Build the UPI payment URI.        val uri = buildUpiUri(payload)        // 4. Build + launch the intent.        return try {            val intent = Intent(Intent.ACTION_VIEW).apply {                data = uri                addFlags(Intent.FLAG_ACTIVITY_NEW_TASK)            }            context.startActivity(intent)            Timber.tag(TAG).i("UPI payment intent launched: $uri")            PaymentIntentResult.SUCCESS(payload.upiId, payload.amount)        } catch (t: Throwable) {            Timber.tag(TAG).e("No UPI app installed or intent failed", t)            PaymentIntentResult.NO_UPI_APP(payload.upiId)        }    }    /**     * Handle a scanned Pix QR code (Brazil — LATAM Regional Pack).     */    suspend fun handlePixQr(payload: QrPayload.PixPayload): PaymentIntentResult {        Timber.tag(TAG).i("Handling Pix QR: pixKey=${payload.pixKey}, amount=${payload.amount}")        if (!region.supports(QrPayloadType.PIX)) {            return PaymentIntentResult.REGION_NOT_SUPPORTED(region)        }        // Pix payment apps use the raw EMV QR string, not a custom URI scheme.        // Copy to clipboard + open the user's bank app.        return try {            val clipboard = context.getSystemService(Context.CLIPBOARD_SERVICE) as? android.content.ClipboardManager ?: return PaymentIntentResult.FAILED("ClipboardManager unavailable")            clipboard.setPrimaryClip(                android.content.ClipData.newPlainText("Pix QR", payload.pixKey)            )            Timber.tag(TAG).i("Pix QR copied to clipboard: ${payload.pixKey}")            PaymentIntentResult.SUCCESS(payload.pixKey, payload.amount)        } catch (t: Throwable) {            Timber.tag(TAG).e("Pix QR handling failed", t)            PaymentIntentResult.FAILED("Failed to copy Pix QR: ${t.message}")        }    }    /**     * Handle a scanned PromptPay QR code (Thailand — SEA Regional Pack).     */    suspend fun handlePromptPayQr(payload: QrPayload.PromptPayPayload): PaymentIntentResult {        Timber.tag(TAG).i("Handling PromptPay QR: id=${payload.promptPayId}, amount=${payload.amount}")        if (!region.supports(QrPayloadType.PROMPTPAY)) {            return PaymentIntentResult.REGION_NOT_SUPPORTED(region)        }        // PromptPay typically uses banking apps that scan the QR directly.        // Copy the ID to clipboard as fallback.        return try {            val clipboard = context.getSystemService(Context.CLIPBOARD_SERVICE) as? android.content.ClipboardManager ?: return PaymentIntentResult.FAILED("ClipboardManager unavailable")            clipboard.setPrimaryClip(                android.content.ClipData.newPlainText("PromptPay ID", payload.promptPayId)            )            Timber.tag(TAG).i("PromptPay ID copied to clipboard: ${payload.promptPayId}")            PaymentIntentResult.SUCCESS(payload.promptPayId, payload.amount)        } catch (t: Throwable) {            Timber.tag(TAG).e("PromptPay QR handling failed", t)            PaymentIntentResult.FAILED("Failed to copy PromptPay ID: ${t.message}")        }    }    /**     * Handle a scanned DuitNow QR code (Malaysia — SEA Regional Pack).     */    suspend fun handleDuitNowQr(payload: QrPayload.DuitNowPayload): PaymentIntentResult {        Timber.tag(TAG).i("Handling DuitNow QR: id=${payload.duitNowId}, amount=${payload.amount}")        if (!region.supports(QrPayloadType.DUITNOW)) {            return PaymentIntentResult.REGION_NOT_SUPPORTED(region)        }        return try {            val clipboard = context.getSystemService(Context.CLIPBOARD_SERVICE) as? android.content.ClipboardManager ?: return PaymentIntentResult.FAILED("ClipboardManager unavailable")            clipboard.setPrimaryClip(                android.content.ClipData.newPlainText("DuitNow ID", payload.duitNowId)            )            Timber.tag(TAG).i("DuitNow ID copied to clipboard: ${payload.duitNowId}")            PaymentIntentResult.SUCCESS(payload.duitNowId, payload.amount)        } catch (t: Throwable) {            Timber.tag(TAG).e("DuitNow QR handling failed", t)            PaymentIntentResult.FAILED("Failed to copy DuitNow ID: ${t.message}")        }    }    /**     * Route a generic [QrPayload] to the appropriate handler based on type.     *     * @return the [PaymentIntentResult].     */    suspend fun handle(payload: QrPayload): PaymentIntentResult {        return when (payload) {            is QrPayload.UpiPayload -> handleUpiQr(payload)            is QrPayload.PixPayload -> handlePixQr(payload)            is QrPayload.PromptPayPayload -> handlePromptPayQr(payload)            is QrPayload.DuitNowPayload -> handleDuitNowQr(payload)            else -> PaymentIntentResult.NOT_A_PAYMENT_QR        }    }    /**     * Build the `upi://pay?...` URI from a [QrPayload.UpiPayload].     *     * Parameters (per NPCI UPI spec):     *  - `pa` — Payee Address (UPI ID) — REQUIRED     *  - `pn` — Payee Name     *  - `am` — Amount     *  - `cu` — Currency (default INR)     *  - `tn` — Transaction Note     *  - `mc` — Merchant Code     */    internal fun buildUpiUri(payload: QrPayload.UpiPayload): Uri {        val uriBuilder = Uri.Builder()            .scheme("upi")            .authority("pay")            .appendQueryParameter("pa", payload.upiId)        payload.payeeName?.let { uriBuilder.appendQueryParameter("pn", it) }        payload.amount?.let { uriBuilder.appendQueryParameter("am", it.toString()) }        uriBuilder.appendQueryParameter("cu", payload.currency)        payload.note?.let { uriBuilder.appendQueryParameter("tn", it) }        payload.merchantCode?.let { uriBuilder.appendQueryParameter("mc", it) }        return uriBuilder.build()    }    /**     * Check if a UPI app is installed on the device.     *     * Common UPI apps in India:     *  - Google Pay (com.google.android.apps.nbu.paisa.user)     *  - PhonePe (com.phonepe.app)     *  - Paytm (net.one97.paytm)     *  - BHIM (in.org.npci.upiapp)     *  - Amazon Pay (com.amazon.mShop.android.shopping)     */    fun isUpiAppInstalled(): Boolean {        val packageManager = context.packageManager        val upiApps = listOf(            "com.google.android.apps.nbu.paisa.user",  // Google Pay            "com.phonepe.app",                           // PhonePe            "net.one97.paytm",                           // Paytm            "in.org.npci.upiapp",                        // BHIM            "com.amazon.mShop.android.shopping",         // Amazon Pay        )        return upiApps.any { packageName ->            try {                @Suppress("DEPRECATION")                packageManager.getPackageInfo(packageName, 0)                true            } catch (e: android.content.pm.PackageManager.NameNotFoundException) {                false            }        }    }    private companion object {        private const val TAG = "UpiQrHandler"    }}// ──────────────────────────────────────────────────────────────────────────/** Result of a payment intent launch. */sealed interface PaymentIntentResult {    /** Payment intent launched successfully. */    data class SUCCESS(        val paymentId: String,  // UPI ID / Pix key / PromptPay ID / DuitNow ID        val amount: Double?,    ) : PaymentIntentResult    /** Invalid payload (e.g., malformed UPI ID). */    data class INVALID_PAYLOAD(val reason: String) : PaymentIntentResult    /** No UPI app installed on the device. */    data class NO_UPI_APP(val upiId: String) : PaymentIntentResult    /** Region not supported (e.g., UPI scanned in LATAM region). */    data class REGION_NOT_SUPPORTED(val region: RegionalQrFormat) : PaymentIntentResult    /** Not a payment QR code. */    data object NOT_A_PAYMENT_QR : PaymentIntentResult    /** Failed to launch payment intent. */    data class FAILED(val reason: String) : PaymentIntentResult}